func (this *Indodax) ParseTransaction(transaction any, optionalArgs ...any) any {
	currency := GetArg(optionalArgs, 0, nil)
	_ = currency
	if (InOp(transaction, "coin")) || (InOp(transaction, "fiatCurrency")) || (InOp(transaction, "withdrawStatus")) || (InOp(transaction, "depositStatus")) || (InOp(transaction, "txType")) {
		return this.ParseV2Transaction(transaction, currency)
	}
	//
	// withdraw
	//
	//     {
	//         "success": 1,
	//         "status": "approved",
	//         "withdraw_currency": "xrp",
	//         "withdraw_address": "rwWr7KUZ3ZFwzgaDGjKBysADByzxvohQ3C",
	//         "withdraw_amount": "10000.00000000",
	//         "fee": "2.00000000",
	//         "amount_after_fee": "9998.00000000",
	//         "submit_time": "1509469200",
	//         "withdraw_id": "xrp-12345",
	//         "txid": "",
	//         "withdraw_memo": "123123"
	//     }
	//
	// transHistory
	//
	//     {
	//         "status": "success",
	//         "type": "coupon",
	//         "rp": "115205",
	//         "fee": "500",
	//         "amount": "114705",
	//         "submit_time": "1539844166",
	//         "success_time": "1539844189",
	//         "withdraw_id": "1783717",
	//         "tx": "BTC-IDR-RDTVVO2P-ETD0EVAW-VTNZGMIR-HTNTUAPI-84ULM9OI",
	//         "sender": "boris",
	//         "used_by": "viginia88"
	//     }
	//
	//     {
	//         "status": "success",
	//         "btc": "0.00118769",
	//         "amount": "0.00118769",
	//         "success_time": "1539529208",
	//         "deposit_id": "3602369",
	//         "tx": "c816aeb35a5b42f389970325a32aff69bb6b2126784dcda8f23b9dd9570d6573"
	//     },
	var status *string = this.SafeString(transaction, "status")
	var timestamp *int64 = this.SafeTimestamp2(transaction, "success_time", "submit_time")
	var depositId *string = this.SafeString(transaction, "deposit_id")
	var feeCost *float64 = this.SafeNumber(transaction, "fee")
	var fee any = nil
	if feeCost != nil {
		fee = map[string]any{
			"currency": this.SafeCurrencyCode(nil, currency),
			"cost":     feeCost,
			"rate":     nil,
		}
	}
	return map[string]any{
		"id":          this.SafeString2(transaction, "withdraw_id", "deposit_id"),
		"txid":        this.SafeString2(transaction, "txid", "tx"),
		"timestamp":   timestamp,
		"datetime":    this.Iso8601(timestamp),
		"network":     nil,
		"addressFrom": nil,
		"address":     this.SafeString(transaction, "withdraw_address"),
		"addressTo":   nil,
		"amount":      this.SafeNumberN(transaction, []any{"amount", "withdraw_amount", "deposit_amount"}),
		"type": func() string {
			if depositId == nil {
				return "withdraw"
			}
			return "deposit"
		}(),
		"currency": this.SafeCurrencyCode(nil, currency),
		"status":   this.ParseTransactionStatus(status),
		"updated":  nil,
		"tagFrom":  nil,
		"tag":      nil,
		"tagTo":    nil,
		"comment":  this.SafeString(transaction, "withdraw_memo"),
		"internal": nil,
		"fee":      fee,
		"info":     transaction,
	}
}
func (this *Indodax) ParseTransactionStatus(status *string) *string {
	var statuses map[string]any = map[string]any{
		"success": "ok",
		"pending": "pending",
		"failed":  "failed",
	}
	return this.SafeString(statuses, status, status)
}

